public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }
    int count = 0;
    int year = Y;
    while (count < N) {
        if (isLeapYear(year)) {
            count++;
        }
        year++;
    }
    return year - 1;
}

private static boolean isLeapYear(int year) {
    if (year % 400 == 0) {
        return true;
    }
    if (year % 100 == 0) {
        return false;
    }
    return year % 4 == 0;
}

