public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be positive");
    }
    if (N <= 2) {
        return 0;
    }
    // Time grows linearly: 2 minutes for 4 people, 4 minutes for 5, 6 for 6,
    // hence formula 2 * (N - 3)
    return 2 * (N - 3);
}

public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be positive");
    }
    int leftCount = N / 2;            // floor(N/2)
    int rightCount = (N + 1) / 2;     // ceil(N/2)
    return leftCount * (rightCount - 1);
}

