public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    Set<String> substrings = new HashSet<>();
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            continue;
        }
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                substrings.add(s.substring(i, j));
            }
        }
    }

    int maxLen = 0;
    for (String sub : substrings) {
        String rev = new StringBuilder(sub).reverse().toString();
        if (substrings.contains(rev)) {
            int currentLen = sub.length();
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        }
    }
    return maxLen;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Handle null strings as empty
    List<String> processed = new ArrayList<>();
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            s = "";
        }
        processed.add(s);
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    String first = processed.get(0);
    // Try lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            candidates.add(first.substring(i, i + len));
        }
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : processed) {
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    List<String> cleaned = new java.util.ArrayList<>();
    for (String s : strings) {
        if (s == null) {
            s = "";
        }
        cleaned.add(s);
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    int low = 1, high = minLen, best = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (hasCommonSubstring(cleaned, mid)) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return best;
}

private boolean hasCommonSubstring(List<String> strings, int len) {
    String base = strings.get(0);
    java.util.HashSet<String> candidates = new java.util.HashSet<>();
    for (int i = 0; i <= base.length() - len; i++) {
        candidates.add(base.substring(i, i + len));
    }
    if (candidates.isEmpty()) {
        return false;
    }
    for (String candidate : candidates) {
        String rev = new StringBuilder(candidate).reverse().toString();
        boolean matchAll = true;
        for (int idx = 1; idx < strings.size(); idx++) {
            String s = strings.get(idx);
            if (!s.contains(candidate) && !s.contains(rev)) {
                matchAll = false;
                break;
            }
        }
        if (matchAll) {
            return true;
        }
    }
    return false;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    if (cols == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;

    // Simple stack implementation using arrays to avoid imports
    int stackSize = rows * cols * 2; // each position needs two slots (row, col)
    int[] stack = new int[stackSize];
    int top = -1;

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                depositCount++;
                // Push starting position onto stack
                top++;
                stack[top++] = r;
                top++;
                stack[top++] = c;
                visited[r][c] = true;

                // DFS using stack
                while (top >= 0) {
                    top--;
                    int col = stack[top--];
                    int row = stack[top--];

                    // Explore neighbors
                    if (row > 0 && grid[row - 1][col] == '@' && !visited[row - 1][col]) {
                        visited[row - 1][col] = true;
                        top++;
                        stack[top++] = row - 1;
                        top++;
                        stack[top++] = col;
                    }
                    if (row < rows - 1 && grid[row + 1][col] == '@' && !visited[row + 1][col]) {
                        visited[row + 1][col] = true;
                        top++;
                        stack[top++] = row + 1;
                        top++;
                        stack[top++] = col;
                    }
                    if (col > 0 && grid[row][col - 1] == '@' && !visited[row][col - 1]) {
                        visited[row][col - 1] = true;
                        top++;
                        stack[top++] = row;
                        top++;
                        stack[top++] = col - 1;
                    }
                    if (col < cols - 1 && grid[row][col + 1] == '@' && !visited[row][col + 1]) {
                        visited[row][col + 1] = true;
                        top++;
                        stack[top++] = row;
                        top++;
                        stack[top++] = col + 1;
                    }
                }
            }
        }
    }

    return depositCount;
}

