private static void dfs(char[][] grid, boolean[][] visited, int r, int c, int[][] directions) {
    int rows = grid.length;
    int cols = grid[0].length;
    java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
    stack.push(new int[]{r, c});
    visited[r][c] = true;
    while (!stack.isEmpty()) {
        int[] cell = stack.pop();
        int cr = cell[0];
        int cc = cell[1];
        for (int[] d : directions) {
            int nr = cr + d[0];
            int nc = cc + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (!visited[nr][nc] && grid[nr][nc] == '@') {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    if (N == 0) {
        return 1; // empty plane has one region
    }
    // Use long to avoid intermediate overflow
    long result = 3L * N * N - 3L * N + 2L;
    if (result > Integer.MAX_VALUE) {
        // If result exceeds int range, clamp to Integer.MAX_VALUE
        return Integer.MAX_VALUE;
    }
    return (int) result;
}

