public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (start == null || end == null || paths == null) return "cannot be travelled";
        if (start.length == 0 || end.length == 0) return "cannot be travelled";
        int startNode = start[0];
        int endNode = end[0];
        java.util.HashMap<Integer, java.util.ArrayList<Integer>> adj = new java.util.HashMap<>();
        java.util.HashSet<Integer> nodes = new java.util.HashSet<>();
        nodes.add(startNode);
        nodes.add(endNode);
        for (int[] edge : paths) {
            if (edge == null || edge.length < 2) continue;
            int a = edge[0];
            int b = edge[1];
            nodes.add(a);
            nodes.add(b);
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
        if (!nodes.contains(startNode) || !nodes.contains(endNode)) return "cannot be travelled";
        java.util.Queue<Integer> queue = new java.util.LinkedList<>();
        java.util.HashSet<Integer> visited = new java.util.HashSet<>();
        queue.add(startNode);
        visited.add(startNode);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endNode) return "can be travelled";
            java.util.List<Integer> neighbors = adj.get(cur);
            if (neighbors != null) {
                for (int nei : neighbors) {
                    if (!visited.contains(nei)) {
                        visited.add(nei);
                        queue.add(nei);
                    }
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    try {
        // Split the input string by whitespace
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date";
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        // Validate month range
        if (month < 1 || month > 12) {
            return "Invalid date";
        }

        // Attempt to construct a LocalDate which will validate day and year
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        // Get the full month name
        String[] monthNames = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        String monthName = monthNames[month - 1];

        // Get the full weekday name
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
        String weekdayName = dayOfWeek.getDisplayName(
            java.time.format.TextStyle.FULL,
            java.util.Locale.ENGLISH
        );

        // Format the output string
        return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
    } catch (Exception e) {
        // Handles NumberFormatException, DateTimeException, etc.
        return "Invalid date";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Input must contain month, day, and year");
        }

        int month = Integer.parseInt(parts[0]);
        int day   = Integer.parseInt(parts[1]);
        int year  = Integer.parseInt(parts[2]);

        // Basic range checks
        if (year <= 0) {
            throw new IllegalArgumentException("Year must be positive");
        }
        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }

        // Determine days in month, accounting for leap years
        int daysInMonth;
        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                daysInMonth = 31;
                break;
            case 4: case 6: case 9: case 11:
                daysInMonth = 30;
                break;
            case 2:
                boolean isLeap = (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
                daysInMonth = isLeap ? 29 : 28;
                break;
            default:
                daysInMonth = 30; // fallback, shouldn't reach here
        }

        if (day < 1 || day > daysInMonth) {
            throw new IllegalArgumentException("Day out of range for the given month and year");
        }

        // Create Calendar to compute weekday
        java.util.GregorianCalendar cal = new java.util.GregorianCalendar(year, month - 1, day);
        int dayOfWeekInt = cal.get(java.util.Calendar.DAY_OF_WEEK);

        String[] monthNames = {
            "", "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        String[] dayNames = {
            "", // index 0 unused
            "Sunday",  "Monday",   "Tuesday", "Wednesday",
            "Thursday", "Friday",  "Saturday"
        };

        String monthName = monthNames[month];
        String weekDayName = dayNames[dayOfWeekInt];

        return monthName + " " + day + ", " + year + " is a " + weekDayName;
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid numeric value in input", e);
    } catch (Exception e) {
        throw new RuntimeException("An unexpected error occurred", e);
    }
}

