public double trimMean(int[] arr) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = arr.length;
    if (n == 0) {
        return 0.0;
    }
    try {
        int removeCount = (int) Math.floor(n * 0.05);
        if (2 * removeCount >= n) {
            // If removing would eliminate all elements, return 0.0
            return 0.0;
        }
        java.util.Arrays.sort(arr);
        double sum = 0.0;
        for (int i = removeCount; i < n - removeCount; i++) {
            sum += arr[i];
        }
        int remaining = n - 2 * removeCount;
        return sum / remaining;
    } catch (Exception e) {
        // In case of any unexpected runtime issues, return NaN
        return Double.NaN;
    }
}

public double trimMean(int[] arr) {
