        throw new IllegalArgumentException("Input array must not be null.");
    }
    int n = arr.length;
    if (n == 0) {
        throw new IllegalArgumentException("Input array must contain at least one element.");
    }

    // Sort the array in ascending order
    java.util.Arrays.sort(arr);

    // Determine how many elements to trim from each side (5% of the array)
    int k = (int) Math.floor(0.05 * n);

    int start = k;
    int end = n - k; // exclusive end index

    if (start >= end) {
        throw new IllegalArgumentException("Not enough elements to trim according to the 5% rule.");
    }

    double sum = 0.0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }

    int count = end - start;
    return sum / count;
}

