public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // odd number of elements cannot be fully paired
    }
    // Use array for counts if k is reasonably small, otherwise use HashMap
    // For simplicity, we assume k fits into array bounds
    int[] freq = new int[k];
    for (int val : arr) {
        int r = val % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    for (int r = 0; r < k; r++) {
        int complement = (k - r) % k;
        if (freq[r] == 0) {
            continue;
        }
        if (r == complement) {
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int val : arr) {
        int r = Math.floorMod(val, k);
        freq[r]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            continue; // already handled when k is even
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    try {
        if (arr == null || k <= 0 || arr.length % 2 != 0) {
            return false;
        }
        int[] remainderCount = new int[k];
        for (int num : arr) {
            int rem = ((num % k) + k) % k;
            remainderCount[rem]++;
        }
        // Check remainder 0
        if (remainderCount[0] % 2 != 0) {
            return false;
        }
        // If k is even, check remainder k/2
        if (k % 2 == 0) {
            if (remainderCount[k / 2] % 2 != 0) {
                return false;
            }
        }
        // Check pairs of remainders
        for (int r = 1; r <= k / 2; r++) {
            if (r == k - r) {
                // Already handled in even k case
                continue;
            }
            if (remainderCount[r] != remainderCount[k - r]) {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

public boolean canArrange(int[] arr, int k) {
    // Validate inputs
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }

    int n = arr.length;
    int[] freq = new int[k];

    // Count frequencies of remainders
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        freq[rem]++;
    }

    // Remainder 0 must have even count
    if ((freq[0] & 1) == 1) { // odd number
        return false;
    }

    // If k is even, handle the special case of remainder k/2
    int limit = k / 2;
    for (int rem = 1; rem < limit; rem++) {
        if (freq[rem] != freq[k - rem]) {
            return false;
        }
    }

    // If k is even, check remainder k/2
    if ((k & 1) == 0) { // k is even
        if ((freq[limit] & 1) == 1) { // odd
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if (arr.length % 2 != 0) {
        return false; // Odd number of elements cannot form pairs
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // Normalize remainder to be non-negative
        freq[r]++;
    }
    // Remainder 0 must occur even number of times
    if (freq[0] % 2 != 0) {
        return false;
    }
    // For each remainder r, need matching count with complement (k - r)
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // Case when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) continue;
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj.get(u).add(v);
        adj.get(v).add(u);
    }
    return dfs(0, -1, adj, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int time = 0;
    for (int nei : adj.get(node)) {
        if (nei == parent) continue;
        int t = dfs(nei, node, adj, hasApple);
        if (t > 0 || hasApple[nei]) {
            time += t + 2;
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    if (edges == null || hasApple == null) {
        throw new IllegalArgumentException("Null argument");
    }
    if (hasApple.length != n) {
        throw new IllegalArgumentException("hasApple length mismatch");
    }
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            continue;
        }
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge indices out of bounds");
        }
        adj[u].add(v);
        adj[v].add(u);
    }
    int[] time = new int[1];
    dfs(0, -1, adj, hasApple, time);
    return time[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Validate input
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length != 2 || e[0] < 0 || e[0] >= n || e[1] < 0 || e[1] >= n) {
                continue; // ignore malformed edges
            }
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
    }
    boolean[] visited = new boolean[n];
    int[] total = new int[1]; // holds total time
    dfs(0, graph, hasApple, visited, total);
    return total[0];
}

private boolean dfs(int node, java.util.List<Integer>[] graph, boolean[] hasApple,
                     boolean[] visited, int[] total) {
    visited[node] = true;
    boolean has = hasApple[node];
    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            boolean childHas = dfs(neighbor, graph, hasApple, visited, total);
            if (childHas) {
                total[0] += 2; // go to child and back
                has = true;
            }
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }

    // Frequency array for all possible char values (0-65535)
    int[] freq = new int[65536];
    for (int i = 0; i < n; i++) {
        freq[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Ascending pass: start with the smallest available character
        int cur = 0;
        while (cur < freq.length && freq[cur] == 0) {
            cur++;
        }
        if (cur >= freq.length) {
            break; // No characters left
        }
        result.append((char) cur);
        freq[cur]--;
        remaining--;

        while (remaining > 0) {
            int next = cur + 1;
            while (next < freq.length && freq[next] == 0) {
                next++;
            }
            if (next >= freq.length) {
                break;
            }
            result.append((char) next);
            freq[next]--;
            remaining--;
            cur = next;
        }

        // Descending pass: start with the largest available character
        int curDesc = freq.length - 1;
        while (curDesc >= 0 && freq[curDesc] == 0) {
            curDesc--;
        }
        if (curDesc < 0) {
            break; // No characters left
        }
        result.append((char) curDesc);
        freq[curDesc]--;
        remaining--;

        while (remaining > 0) {
            int prev = curDesc - 1;
            while (prev >= 0 && freq[prev] == 0) {
                prev--;
            }
            if (prev < 0) {
                break;
            }
            result.append((char) prev);
            freq[prev]--;
            remaining--;
            curDesc = prev;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder(s.length());
    while (!map.isEmpty()) {
        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        while (entry != null) {
            char c = entry.getKey();
            sb.append(c);
            int count = entry.getValue() - 1;
            if (count == 0) {
                map.remove(c);
            } else {
                map.put(c, count);
            }
            entry = map.higherEntry(c);
        }
        if (map.isEmpty()) break;
        // Descending phase
        entry = map.lastEntry();
        while (entry != null) {
            char c = entry.getKey();
            sb.append(c);
            int count = entry.getValue() - 1;
            if (count == 0) {
                map.remove(c);
            } else {
                map.put(c, count);
            }
            entry = map.lowerEntry(c);
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("String must contain only lowercase letters");
        }
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending phase
        int i = 0;
        while (i < 26 && freq[i] == 0) {
            i++;
        }
        while (i < 26) {
            sb.append((char) ('a' + i));
            freq[i]--;
            remaining--;
            i++; // move to next greater
            while (i < 26 && freq[i] == 0) {
                i++;
            }
        }
        if (remaining == 0) {
            break;
        }
        // Descending phase
        int j = 25;
        while (j >= 0 && freq[j] == 0) {
            j--;
        }
        while (j >= 0) {
            sb.append((char) ('a' + j));
            freq[j]--;
            remaining--;
            j--; // move to next smaller
            while (j >= 0 && freq[j] == 0) {
                j--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int v : nums) sum += v;
    // dp[k] holds all possible sums using k elements
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    int processed = 0;
    for (int num : nums) {
        processed++;
        for (int k = Math.min(processed, n); k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((long)sum * k % n != 0) continue;
        int target = (int)((long)sum * k / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    // sums[k] will contain all possible sums achievable with k elements
    java.util.HashSet<Integer>[] sums = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) sums[i] = new java.util.HashSet<>();
    sums[0].add(0);

    for (int num : nums) {
        // iterate k downwards to avoid using the same element multiple times
        for (int k = n - 1; k >= 0; k--) {
            for (int s : sums[k]) {
                int newSum = s + num;
                int newK = k + 1;
                // Check for valid subset (non-empty and not whole array)
                if (newK != n && newK != 0) {
                    if ((long)newSum * n == (long)totalSum * newK) {
                        return true;
                    }
                }
                sums[newK].add(newSum);
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    // dp[k][s] indicates whether a subset of size k with sum s exists
    boolean[][] dp = new boolean[n + 1][total + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k in reverse to avoid reuse of the same number
        for (int k = n - 1; k >= 0; k--) {
            for (int s = total - num; s >= 0; s--) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }
    // check for any valid subset size k
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Try all possible subset sizes up to n/2
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum must be integer
        }
        long targetLong = (totalSum * k) / n;
        int target = (int) targetLong;
        // DP arrays of HashSet to store achievable sums for each subset size
        @SuppressWarnings("unchecked")
        HashSet<Integer>[] dp = new HashSet[k + 1];
        dp[0] = new HashSet<>();
        dp[0].add(0);
        int currentMaxSize = 0;
        for (int num : nums) {
            int nextMaxSize = Math.min(currentMaxSize + 1, k);
            // Update from higher sizes to lower to avoid reuse within same iteration
            for (int size = nextMaxSize; size >= 1; size--) {
                if (dp[size - 1] == null) {
                    continue;
                }
                if (dp[size] == null) {
                    dp[size] = new HashSet<>();
                }
                for (int partialSum : dp[size - 1]) {
                    int newSum = partialSum + num;
                    if (newSum == target) {
                        return true;
                    }
                    dp[size].add(newSum);
                }
            }
            currentMaxSize = nextMaxSize;
        }
        if (dp[k] != null && dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int num : nums) total += num;
    // sumSets[k] holds all possible sums of subsets with size k
    @SuppressWarnings("unchecked")
    Set<Integer>[] sumSets = new Set[n + 1];
    for (int i = 0; i <= n; i++) sumSets[i] = new HashSet<>();
    sumSets[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using updated values in the same iteration
        for (int sz = n - 1; sz >= 1; --sz) {
            if (sumSets[sz - 1].isEmpty()) continue;
            for (int prevSum : sumSets[sz - 1]) {
                sumSets[sz].add(prevSum + num);
            }
        }
    }
    // check for any subset size k (1..n/2) that achieves the target sum
    for (int k = 1; k <= n / 2; ++k) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (sumSets[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0 || n == 1) {
        // With 0 or 1 step, you can start beyond the first step and reach the top without paying anything.
        return 0;
    }
    // dp[i] is the minimum cost to reach step i (0-indexed).
    // We only need the previous two states to compute the current one.
    int prev2 = 0; // cost to reach step -1 (start point)
    int prev1 = 0; // cost to reach step 0
    for (int i = 2; i <= n; i++) {
        int stepFromOne = prev1 + cost[i - 1];   // come from step i-1
        int stepFromTwo = prev2 + cost[i - 2];   // come from step i-2
        int curr = Math.min(stepFromOne, stepFromTwo);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0 || n == 1) {
        return 0;
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    if (n == 2) {
        return Math.min(prev2, prev1);
    }
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input gracefully
    if (cost == null) {
        return 0;
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    // If there's only one step, we must pay its cost to reach the top
    if (n == 1) {
        return cost[0];
    }

    // Use two variables to keep track of the minimum cost to reach the
    // previous two steps. We start from step 0 or 1, so both costs are 0.
    int costToPrev = 0; // Minimum cost to reach step i-1
    int costToPrevPrev = 0; // Minimum cost to reach step i-2

    for (int i = 2; i <= n; i++) {
        int minCost = Integer.MAX_VALUE;
        // Option 1: come from step i-1
        minCost = Math.min(minCost, costToPrev + cost[i - 1]);
        // Option 2: come from step i-2
        minCost = Math.min(minCost, costToPrevPrev + cost[i - 2]);

        // Update rolling values
        costToPrevPrev = costToPrev;
        costToPrev = minCost;
    }

    return costToPrev;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] = minimum cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dp[i - 1] + cost[i - 1];
        int costFromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costFromPrev, costFromPrevPrev);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // If only one step, you can start at the top (index 1) with cost 0
    if (n == 1) {
        return 0;
    }
    // dp[i] represents the minimal cost to reach step i
    int[] dp = new int[n];
    // Starting on step 0 or 1 does not incur any cost
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    // Top of the floor is one step beyond the last index.
    // So the minimal cost to reach the top is the min of reaching the last or the second-to-last step.
    return Math.min(dp[n - 1], dp[n - 2]);
}

