            seen[val] = true;
        }

        // Check if all patterns were seen
        for (boolean present : seen) {
            if (!present) {
                return false;
            }
        }
        return true;
    } else {
        java.util.Set<Integer> seenSet = new java.util.HashSet<>( (int)Math.min(total, Integer.MAX_VALUE) );
        int mask = (k == 32) ? -1 : ((1 << k) - 1);
