public int minOperations(int n) {
    if (n <= 1) {
        // For n == 0 or 1, no operations are needed
        return 0;
    }
    long operations = 0L;
    int startIdx = (n + 1) / 2; // first index where arr[i] > n
    for (int i = startIdx; i < n; i++) {
        int val = 2 * i + 1;
        operations += val - n; // val > n guaranteed here
    }
    // Since the problem guarantees the operations fit in an int
    return (int) operations;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    // k = floor((n + 1) / 2)
    int k = (n + 1) / 2;
    long countHigh = (long) n - k;           // number of elements greater than the target
    long ops = (long) k * countHigh;        // total operations needed
    if (ops > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) ops;
}

public int minOperations(int n) {
