    // Generate all Fibonacci numbers up to k (no need for more than the 44th for 32‑bit int limits)
    int[] fib = new int[45];
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        // Check for overflow or exceeding k
        if (next > k || next < 0) {
            break;
        }
        fib[size++] = next;
    }

    // Greedy selection of Fibonacci numbers (Zeckendorf representation)
    int count = 0;
    int remaining = k;
    while (remaining > 0) {
        for (int i = size - 1; i >= 0; i--) {
            if (fib[i] <= remaining) {
                remaining -= fib[i];
                count++;
                break;
            }
        }
    }

    return count;
}

