    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1); // F1
    fibs.add(1); // F2
    long next = 2; // F3
    while (next <= k) {
        fibs.add((int) next);
        int size = fibs.size();
        next = (long) fibs.get(size - 1) + fibs.get(size - 2);
    }
    // Greedy subtraction from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50];
    fib[0] = 1;
    fib[1] = 1;
    int len = 2;
    while (true) {
        long next = (long) fib[len - 1] + fib[len - 2];
        if (next > k) {
            break;
        }
        fib[len] = (int) next;
        len++;
        if (len >= fib.length) {
            break;
        }
    }

    int count = 0;
    int remaining = k;
    while (remaining > 0) {
        for (int i = len - 1; i >= 0; i--) {
            if (fib[i] <= remaining) {
                remaining -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int sqrt = (int) Math.sqrt(n);
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int count = small.size() + large.size();
    if (k > count) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idxInLarge = large.size() - (k - small.size());
        return large.get(idxInLarge);
    }
}

