private int dfs(String s, int pos, java.util.Set<String> used) {
    if (pos == s.length()) {
        return 0;
    }
    int max = 0;
    for (int i = pos + 1; i <= s.length(); i++) {
        String sub = s.substring(pos, i);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        int result = 1 + dfs(s, i, used);
        if (result > max) {
            max = result;
        }
        used.remove(sub);
    }
    return max;
}

