public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int[] best = new int[1];
    best[0] = 1; // at least one part is possible
    Set<String> used = new HashSet<>();
    backtrack(s, 0, used, best);
    return best[0];
}

private void backtrack(String s, int index, Set<String> used, int[] best) {
    int n = s.length();
    if (index == n) {
        best[0] = Math.max(best[0], used.size());
        return;
    }
    // Prune if remaining characters cannot exceed current best
    // Even if we split each remaining char, max count = used.size() + (n - index)
    if (used.size() + (n - index) <= best[0]) {
        return;
    }
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        backtrack(s, end, used, best);
        used.remove(sub);
    }
}

