private int dfs(String s, int index, java.util.Set<String> used) {
    if (index == s.length()) {
        return used.size();
    }
    int best = 0;
    for (int i = index + 1; i <= s.length(); i++) {
        String part = s.substring(index, i);
        if (used.contains(part)) {
            continue;
        }
        used.add(part);
        int current = dfs(s, i, used);
        if (current > best) {
            best = current;
        }
        used.remove(part);
    }
    return best;
}

