private int dfs(int index, Set<String> used, String s) {
    int n = s.length();
    if (index == n) {
        return 0;
    }
    int max = 0;
    StringBuilder sb = new StringBuilder();
    for (int i = index; i < n; i++) {
        sb.append(s.charAt(i));
        String cur = sb.toString();
        if (!used.contains(cur)) {
            used.add(cur);
            int count = 1 + dfs(i + 1, used, s);
            if (count > max) {
                max = count;
            }
            used.remove(cur);
        }
    }
    return max;
}

