    // Start with all 'a's which give the minimal lexicographic order
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // the additional sum we need to distribute
    // Increment characters from right to left to keep lexicographic order minimal
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
