    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    // Remaining value to distribute
    int remaining = k - n;
    // Distribute the additional value from the end to keep string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increase = Math.min(25, remaining); // max we can add to a character ('a' + 25 = 'z')
        result[i] = (char) ('a' + increase);
