}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26L * n) {
        return "";
    }
    char[] result = new char[n];
    int remainingSum = k;
    for (int i = n - 1; i >= 0; i--) {
        int positionsRemaining = i + 1;
        int maxAllowed = remainingSum - (positionsRemaining - 1);
        int value = Math.min(26, Math.max(1, maxAllowed));
        result[i] = (char) ('a' + value - 1);
        remainingSum -= value;
    }
    return new String(result);
}

