public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array is null or empty");
    }
    int ones = 0;
    int twos = 0;
    for (int x : nums) {
        twos |= ones & x;      // update twos with bits that have appeared twice
        ones ^= x;             // update ones with bits that have appeared once
        int mask = ~(ones & twos); // remove bits that have appeared three times
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (nums.length == 0) {
        throw new IllegalArgumentException("Input array must contain at least one element");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >> i) & 1) != 0) {
                bitCount[i] = (bitCount[i] + 1) % 3;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (bitCount[i] != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

