        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        if (factor > Long.MAX_VALUE / 10) {
            break;
        }
        factor *= 10;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    // Returns the number of times the digit '1' appears in all integers from 0 to n inclusive.
    if (n <= 0) {
        // For n <= 0, there are no numbers with a '1' digit in the range [0, n].
        return 0;
    }

    long count = 0;          // Use long to prevent intermediate overflow.
    long factor = 1L;        // Represents the current power of 10 being examined.

    // Iterate through each digit position of n.
    while (factor <= n) {
        long lowerNums = n - (n / factor) * factor;           // Digits to the right of current position.
        long currentDigit = (n / factor) % 10;                // Digit at current position.
        long higherNums = n / (factor * 10);                  // Digits to the left of current position.

        if (currentDigit == 0) {
            count += higherNums * factor;
        } else if (currentDigit == 1) {
            count += higherNums * factor + lowerNums + 1;
        } else {
            count += (higherNums + 1) * factor;
        }

        factor *= 10;  // Move to the next higher digit position.
    }

    // The final count fits in an int because the maximum possible value
    // for int n (2^31-1) yields less than 2^31 occurrences of '1'.
    return (int) count;
}

public static int countDigitOne(int n) {
