    while (position <= n) {
        long higher = n / (position * 10);
        long current = (n / position) % 10;
        long lower = n % position;

        count += higher * position;
        if (current == 1) {
            count += lower + 1;
        } else if (current > 1) {
            count += position;
        }

        // Avoid overflow of position (though for int n it will break before this)
        if (position > Long.MAX_VALUE / 10) {
            break;
        }
        position *= 10;
    }
    return (int) count;
}

