public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n <= 1) {
        return 1;
    }

    // Precompute whether sum of two numbers is a perfect square
    int maxValue = 0;
    for (int v : A) {
        if (v > maxValue) {
            maxValue = v;
        }
    }
    int maxSum = maxValue * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; ; s++) {
        int sq = s * s;
        if (sq > maxSum) break;
        isSquare[sq] = true;
    }

    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                ok[i][j] = true;
            }
        }
    }

    int totalMasks = 1 << n;
    long[][] dp = new long[totalMasks][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    for (int mask = 1; mask < totalMasks; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            int remaining = (~mask) & (totalMasks - 1);
            for (int nxt = remaining; nxt != 0; nxt &= (nxt - 1)) {
                int nextIndex = Integer.numberOfTrailingZeros(nxt);
                if (ok[last][nextIndex]) {
                    dp[mask | (1 << nextIndex)][nextIndex] += cur;
                }
            }
        }
    }

    long result = 0;
    int fullMask = totalMasks - 1;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return (int) result;
}

public static int squarePermutations(int[] A) {
    try {
        if (A == null || A.length == 0) {
            return 0;
        }
        int n = A.length;
        // Precompute adjacency: can elements i and j be adjacent?
        boolean[][] canAdj = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    int sum = A[i] + A[j];
                    int sqrt = (int)Math.sqrt(sum);
                    canAdj[i][j] = sqrt * sqrt == sum;
                }
            }
        }
        int fullMask = (1 << n) - 1;
        long[][] dp = new long[1 << n][n];
        for (int i = 0; i < n; i++) {
            dp[1 << i][i] = 1;
        }
        for (int mask = 1; mask <= fullMask; mask++) {
            for (int last = 0; last < n; last++) {
                long ways = dp[mask][last];
                if (ways == 0) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask & (1 << nxt)) == 0 && canAdj[last][nxt]) {
                        dp[mask | (1 << nxt)][nxt] += ways;
                    }
                }
            }
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += dp[fullMask][i];
        }
        return (int)total;
    } catch (Exception e) {
        // In case of any runtime exception, return 0 as safe fallback
        return 0;
    }
}

public static int largestRectangleArea(int[] heights) {
    // Handle null or empty input
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];

        // Validate the heights array for negative values
        if (currentHeight < 0) {
            throw new IllegalArgumentException("Heights must be non-negative.");
        }

        // Pop until the current bar is taller than the stack's top
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int topIndex = stack.pop();
            int height = heights[topIndex];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }

        stack.push(i);
    }

    return maxArea;
}

