        int index = 0;
        for (int k = 0; k <= m + n - 2; k++) {
            int lower = Math.max(0, k - (n - 1));
            int upper = Math.min(k, m - 1);
            if (k % 2 == 0) {
                for (int i = upper; i >= lower; i--) {
                    int j = k - i;
                    result[index++] = mat[i][j];
                }
            } else {
                for (int i = lower; i <= upper; i++) {
                    int j = k - i;
                    result[index++] = mat[i][j];
                }
            }
        }
        return result;
    } catch (Exception e) {
        // In case of unforeseen errors, return an empty array
        return new int[0];
    }
}

