                    up = !up;
                } else if (r == 0) {
                    c++;
                    up = !up;
                } else {
                    r--;
                    c++;
                }
            } else {
                if (r == m - 1) {
                    c++;
                    up = !up;
                } else if (c == 0) {
                    r++;
                    up = !up;
                } else {
                    r++;
                    c--;
                }
            }
        }
