public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Step 1: find the pivot
    int pivot = -1;
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            pivot = i;
            break;
        }
    }
    if (pivot == -1) {
        return -1; // already the highest permutation
    }

    // Step 2: find the rightmost successor to pivot
    int successor = -1;
    for (int j = len - 1; j > pivot; j--) {
        if (digits[j] > digits[pivot]) {
            successor = j;
            break;
        }
    }
    if (successor == -1) {
        return -1; // should not happen
    }

    // Step 3: swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 4: reverse the suffix starting at pivot+1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }
    return (int) result;
}

