public static List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] buffer = new char[n];
    char[][] pairs = {{'0','0'}, {'1','1'}, {'6','9'}, {'8','8'}, {'9','6'}};
    char[] centerDigits = {'0','1','8'};
    fill(n, buffer, 0, pairs, centerDigits, result);
    return result;
}

private static void fill(int n, char[] buf, int left, char[][] pairs, char[] centerDigits, java.util.List<String> res) {
    int right = n - 1 - left;
    if (left > right) {
        // All positions filled
        res.add(new String(buf));
        return;
    }
    if (left == right) { // center position for odd length
        for (char c : centerDigits) {
            buf[left] = c;
            res.add(new String(buf));
        }
        return;
    }
    for (int i = 0; i < pairs.length; i++) {
        char a = pairs[i][0];
        char b = pairs[i][1];
        if (left == 0 && a == '0') {
            continue; // no leading zeros for numbers with length > 1
        }
        buf[left] = a;
        buf[right] = b;
        fill(n, buf, left + 1, pairs, centerDigits, res);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[] arr = new char[n];
    backtrack(arr, 0, n - 1, n, result);
    return result;
}

private static void backtrack(char[] arr, int left, int right, int n, List<String> result) {
    if (left > right) {
        result.add(new String(arr));
        return;
    }
    if (left == right) {
        char[] middle = {'0', '1', '8'};
        for (char c : middle) {
            arr[left] = c;
            result.add(new String(arr));
        }
        return;
    }
    for (char[] pair : PAIRS) {
        if (left == 0 && pair[0] == '0' && n != 1) {
            continue;
        }
        arr[left] = pair[0];
        arr[right] = pair[1];
        backtrack(arr, left + 1, right - 1, n, result);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    char[][] pairs = {
        {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}
    };
    char[] str = new char[n];
    dfs(0, n - 1, str, result, pairs, n);
    return result;
}

private static void dfs(int left, int right, char[] str, List<String> result, char[][] pairs, int n) {
    if (left > right) {
        result.add(new String(str));
        return;
    }
    for (char[] pair : pairs) {
        // Skip leading zeros for numbers longer than 1 digit
        if (left == 0 && pair[0] == '0' && n > 1) {
            continue;
        }
        // For the middle position in odd length, only use symmetric pairs
        if (left == right && pair[0] != pair[1]) {
            continue;
        }

        str[left] = pair[0];
        str[right] = pair[1];
        dfs(left + 1, right - 1, str, result, pairs, n);
    }
}

private static void build(java.util.List<String> result, char[] chars, int left, int right) {
    if (left > right) {
        result.add(new String(chars));
        return;
    }
    if (left == right) {
        char[] mid = {'0', '1', '8'};
        for (char c : mid) {
            chars[left] = c;
            build(result, chars, left + 1, right - 1);
        }
        return;
    }
    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'8', '8'},
        {'6', '9'},
        {'9', '6'}
    };
    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0' && chars.length > 1) {
            continue; // avoid leading zero for numbers with length > 1
        }
        chars[left] = pair[0];
        chars[right] = pair[1];
        build(result, chars, left + 1, right - 1);
    }
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
        return cross != 0;
    } catch (Exception e) {
        return false;
    }
}

