    }
    // Check each point validity and distinctness
    for (int i = 0; i < points.length; i++) {
        if (points[i] == null || points[i].length < 2) {
            return false;
        }
        // Compare with previous points for uniqueness
        for (int j = 0; j < i; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false; // duplicate point found
            }
        }
    }
    int[] p0 = points[0];
    int[] p1 = points[1];
    int[] p2 = points[2];

    // Compute vectors p1 - p0 and p2 - p0
    int dx1 = p1[0] - p0[0];
    int dy1 = p1[1] - p0[1];
    int dx2 = p2[0] - p0[0];
    int dy2 = p2[1] - p0[1];

    // Compute cross product to check collinearity
    int cross = dx1 * dy2 - dy1 * dx2;
    return cross != 0;
}

public static boolean isBoomerang(int[][] points) {
    try {
        // Validate input array
        if (points == null || points.length < 3) {
            return false;
        }
        // All points must have two coordinates
        for (int i = 0; i < points.length; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        // For a boomerang we need exactly three distinct points
        int[][] p = new int[][] { points[0], points[1], points[2] };
        // Check for duplicate points
        if ((p[0][0] == p[1][0] && p[0][1] == p[1][1]) ||
            (p[0][0] == p[2][0] && p[0][1] == p[2][1]) ||
            (p[1][0] == p[2][0] && p[1][1] == p[2][1])) {
            return false;
        }
        // Compute cross product to test collinearity
        long x1 = p[0][0], y1 = p[0][1];
        long x2 = p[1][0], y2 = p[1][1];
        long x3 = p[2][0], y3 = p[2][1];
        long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        return cross != 0;
    } catch (Exception e) {
        // Any runtime issue results in false
        return false;
    }
}

