                count++;
            } else {
                if (count > max) {
                    max = count;
                }
                count = 1; // reset for new character
            }
        }

        // Final check in case the longest streak is at the end
        if (count > max) {
            max = count;
        }

        return max;
    } catch (Exception e) {
        // In case of any unexpected runtime error, return 0 as a safe fallback
        return 0;
    }
}

