    }
    int[] dp = new int[n + 1];
    final int INF = Integer.MAX_VALUE;
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = INF;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != INF) {
                int candidate = dp[i - square] + 1;
                if (candidate < dp[i]) {
                    dp[i] = candidate;
                }
            }
        }
    }
    return dp[n];
}

