        char c = s.charAt(i);
        if (c == ' ') {
            if (current.length() > 0) {
                result.append(current.reverse());
                current.setLength(0);
            }
            result.append(' ');
        } else {
            current.append(c);
        }
    }
    if (current.length() > 0) {
        result.append(current.reverse());
    }
