public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int len = s.length();
    if (len == 0) {
        return "";
    }
    StringBuilder result = new StringBuilder(len);
    int wordStart = 0;
    for (int i = 0; i < len; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            int wordLen = i - wordStart;
            if (wordLen > 0) {
                result.append(new StringBuilder(s, wordStart, wordLen).reverse());
            }
            result.append(' ');
            wordStart = i + 1;
        }
    }
    // Append the last word if present
    int wordLen = len - wordStart;
    if (wordLen > 0) {
        result.append(new StringBuilder(s, wordStart, wordLen).reverse());
    }
    return result.toString();
}

